import { playBubbleVoice } from './audio.js';
import { openBank } from './voicebank.js';

// Recordings for the spoken lines outside the story/job pipelines: speech
// bubbles, cutscene subtitles without their own voice, the rondvaart guide.
// Keyed "<speaker>|<text>" like the other manifests, so an edited line goes
// silent instead of playing the wrong recording. Bubbles are recorded per
// voice sex: "~m|<text>" and "~f|<text>". Generated by scripts/tts_lines.py;
// scripts/voice_coverage.mjs lists what is still missing.

const bank = openBank('lines');
const DIR = bank.dir;
const voices = bank.entries;
export const NARRATOR = 'Rikus';

export function lineVoiceFor(speaker, text) {
  return bank.lookup(speaker || NARRATOR, text);
}

// #733: de bank laadt met retry (voicebank.js). Een scène kan hieraan zien of
// een ontbrekende stem aan het laden ligt (even wachten) of definitief mislukt is.
export const lineVoicesReady = () => bank.ready;
export const lineVoicesFailed = () => bank.failed;
export const lineVoicesWhenReady = () => bank.whenReady();
export const lineVoicesRetry = () => bank.retry();

// Same entry with src relative to audio/voicelines/story/, for the story
// cutscenes that resolve recordings against that folder.
export function storyLineVoice(speaker, text) {
  const v = voices[speaker + '|' + text];
  return v ? { src: '../lines/' + v.src, dur: v.dur } : null;
}

function bubbleEntry(text, female) {
  const a = voices[(female ? '~f|' : '~m|') + text], b = voices[(female ? '~m|' : '~f|') + text];
  return a || b || null;
}

export const hasBubbleVoice = (text) => !!bubbleEntry(text, false);

// A bubble's recording as { src, dur } (for lines a minigame says up front).
export function bubbleVoiceFor(text, female) {
  const v = bubbleEntry(text, female);
  return v ? { src: DIR + v.src, dur: v.dur } : null;
}

// Called once per new bubble text; pos = { x, y } of the speaker.
export function speakBubble(text, female, pos) {
  const v = bubbleEntry(text, female);
  return v ? playBubbleVoice(DIR + v.src, v.dur, pos) : false;
}
